class IdentifyCommitteeModule(dspy.Module):
    def __init__(self):
        super().__init__()
        self.predict = dspy.Predict(dspy.Signature('email_body: str -> committee: str', 'Identify the political committee that sponsored a fundraising email.'))

    def forward(self, **inputs):
        result = self.predict(**inputs)
        return dspy.Prediction(committee=result.committee)
